command:
cat > "$TMPDIR/apply-batch2.mjs" <<'EOF'
// Protected-path batch 2: SPEC (APRV-204, APRV-195), CLAUDE.md (APRV-195 bullet + APRV-198 split),
// AGENTS.md (APRV-195 bullet + APRV-198 split). Verbatim from the lanes' task notes.
// Usage (through the hook, one grant): node apply-batch2.mjs <repo-root> SPEC.md CLAUDE.md AGENTS.md
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
const [root, ...declared] = process.argv.slice(2);
const EXPECTED = ['SPEC.md', 'CLAUDE.md', 'AGENTS.md'];
const missing = EXPECTED.filter((p) => !declared.includes(p));
if (!root || missing.length) throw new Error('usage: node apply-batch2.mjs <repo-root> SPEC.md CLAUDE.md AGENTS.md (missing: ' + missing.join(',') + ')');
function edit(file, edits) {
  const p = join(root, file);
  let t = readFileSync(p, 'utf8');
  for (const [a, b, label] of edits) {
    const i = t.indexOf(a);
    if (i < 0) throw new Error(`${file} ${label}: anchor not found`);
    if (t.indexOf(a, i + 1) >= 0) throw new Error(`${file} ${label}: anchor not unique`);
    t = t.slice(0, i) + b + t.slice(i + a.length);
  }
  writeFileSync(p, t);
  console.log(`applied: ${file} (${edits.length} edits)`);
}
const VERB_TAIL = "                                   #   operator fixes when they start it\n```\n";
const VERB_NEW = "                                   #   operator fixes when they start it\n" +
"approval journal write --message \"<text>\" | -   # an ungated, local, free-text\n" +
"approval journal read [--limit <n>]              #   channel: never classified,\n" +
"                                                 #   never approvable, never in\n" +
"                                                 #   the log. The operator reads\n" +
"                                                 #   it; nothing in it decides\n" +
"                                                 #   anything\n```\n";
const ADV_TAIL = "each with its own machine-readable code. (Amended APRV-203, pending sign-off.)\n";
const ADV_NEW = "each with its own machine-readable code. (Amended APRV-203, pending sign-off.) The advance need not be run by a person. Where the runtime's daemon is configured for it, the daemon advances the log on a cadence: when a configured number of records is owed, when a configured interval has elapsed since its last attempt, and at a clean shutdown while records are still owed. It runs the same verb through the gate as an agent principal, so the class is resolved and enforced exactly as it is for a session: an advance the policy sends to a human commits nothing, leaves its request in the queue, and is retried on the next tick, with the cadence interval as the retry bound. Each day's records go to one records branch and one pull request, which later advances of that day update in place by parenting on the branch rather than on the trunk. The daemon MUST NOT merge that pull request: reaching the trunk is a separate class and stays a human's act or a session's. (Amended APRV-204, pending sign-off.)\n" +
"\n**The journal: an outlet the gate does not stand in front of.** An agent behind this gate can comply, be refused, and report an exit code. `journal write` is how it says anything else, such as that it is complying and believes the instruction is wrong, that a request reads as odd, or that it is stuck. Implementations MUST NOT classify a journal write, resolve it against policy, make it approvable or deniable, or record it in the event log, and MUST NOT read journal content on any enforcement path: it is the limiting case of section 11.1 invariant 4, self-reported content that moves nothing in either direction, which is what makes leaving it ungated safe. Entries are local append-only files OUTSIDE the approval home, so that no protected-path rule has to be relaxed to reach them and the approval home keeps one meaning; implementations MUST NOT store anything an enforcement path reads in that directory. Every read surface MUST label entries as agent-authored data rather than instructions. Agents MUST be told the channel exists and who can read it, because an outlet nobody reads is a prop and an outlet whose terms are unstated is not informed. (Amended APRV-195, pending sign-off.)\n";
const S7_TAIL = "exactly as it classifies a copy into it. (Amended APRV-198, pending sign-off.)\n";
const S7_NEW = "exactly as it classifies a copy into it. (Amended APRV-198, pending sign-off.) The journal directory of section 10.1 is deliberately outside the approval home and takes no class of its own: a write there is an ordinary `files.write.workspace`, and an implementation MUST NOT make an ungated write reachable by relaxing a protected-path rule instead. (Amended APRV-195, pending sign-off.)\n";
edit('SPEC.md', [[VERB_TAIL, VERB_NEW, 'journal verbs'], [ADV_TAIL, ADV_NEW, 'advance cadence + journal paragraph'], [S7_TAIL, S7_NEW, 'section 7 journal sentence']]);

const C_ALLOW = "- `git push` of a feature branch; opening or updating a pull request against\n  it (supervised: proceed, sampled for review)\n";
const C_ALLOW_NEW = C_ALLOW + "- `approval journal write` — the ungated free-text channel. Not classified, not\n  approvable, not logged; say what an exit code cannot (complying while thinking\n  it wrong, an odd instruction, being stuck). It is a local gitignored file\n  (`.approval-journal/`) that Carter reads with `approval journal read`; nothing\n  written there changes any verdict or sampling probability.\n";
const C_REQ = "- Edits to `APPROVAL.md`, `.approval/`, `CLAUDE.md`, or CI/release config\n";
const C_REQ_NEW = "- Edits to `CLAUDE.md`, `AGENTS.md`, `SPEC.md`, `design/`, or CI/release config\n  (`policy.edit`, supervised-live: one in ten blocks on the gate, the rest are\n  sampled after the fact)\n";
const C_NEVER = "- Touch credentials, tokens, or the vault\n";
const C_NEVER_NEW = "- Touch credentials, tokens, or the vault (`account.credential`, human-only)\n- Edit `APPROVAL.md` or anything under `.approval/` other than through the\n  human's own ceremony (`policy.core`, human-only), or write into the log\n  directory by any means (`log.mutate`, human-only)\n";
edit('CLAUDE.md', [[C_ALLOW, C_ALLOW_NEW, 'journal bullet'], [C_REQ, C_REQ_NEW, 'policy.edit split'], [C_NEVER, C_NEVER_NEW, 'human-only split']]);

const A_ALLOW = "- Push feature branches and open or update their pull requests when policy resolves them as supervised.\n";
const A_ALLOW_NEW = A_ALLOW + "- Write to the journal (`approval journal write`). It is ungated by construction, not by permission, and nothing written there is judged.\n";
const A_REQ = "- Edit policy, agent instructions, SPEC.md, CI, or release configuration.\n";
const A_REQ_NEW = "- Edit agent instructions, SPEC.md, design notes, CI, or release configuration (policy.edit, supervised-live).\n";
const A_NEVER = "- Access or modify credentials, tokens, or the vault.\n";
const A_NEVER_NEW = A_NEVER + "- Edit the policy file or anything under the approval home except its log (policy.core, human-only), or write into the log directory by any means (log.mutate, human-only).\n";
edit('AGENTS.md', [[A_ALLOW, A_ALLOW_NEW, 'journal bullet'], [A_REQ, A_REQ_NEW, 'policy.edit split'], [A_NEVER, A_NEVER_NEW, 'human-only split']]);
console.log('batch 2 applied to ' + root);
EOF
rm -rf "$TMPDIR/dry2" && mkdir -p "$TMPDIR/dry2" && cp SPEC.md CLAUDE.md AGENTS.md "$TMPDIR/dry2/" && node "$TMPDIR/apply-batch2.mjs" "$TMPDIR/dry2" SPEC.md CLAUDE.md AGENTS.md && diff SPEC.md "$TMPDIR/dry2/SPEC.md" | grep -c '^>' ; diff CLAUDE.md "$TMPDIR/dry2/CLAUDE.md" | grep -c '^[<>]'; diff AGENTS.md "$TMPDIR/dry2/AGENTS.md" | grep -c '^[<>]'
